import { Component, computed, inject } from '@angular/core';
import { toSignal } from '@angular/core/rxjs-interop';
import { ActivatedRoute, Router } from '@angular/router';
import { catchError, EMPTY, map, switchMap } from 'rxjs';
import { ApiService } from '../api.service';
import { showDate } from '../date';
import { Movie, Screening } from '../models';
import { SeatMap } from '../seat-map/seat-map';

interface LoadedScreening {
  screening: Screening;
  movie: Movie;
}

@Component({
  selector: 'app-seat-selection',
  imports: [SeatMap],
  templateUrl: './seat-selection.html',
  styleUrl: './seat-selection.scss',
})
export class SeatSelection {
  private readonly api = inject(ApiService);
  private readonly router = inject(Router);
  private readonly route = inject(ActivatedRoute);

  readonly loaded = toSignal(
    this.route.paramMap.pipe(
      map((params) => Number(params.get('id'))),
      switchMap((id) =>
        this.api.getScreening(id).pipe(
          switchMap((screening) =>
            this.api.getMovie(screening.movieId).pipe(map((movie): LoadedScreening => ({ screening, movie }))),
          ),
          catchError(() => {
            void this.router.navigate(['/']);
            return EMPTY;
          }),
        ),
      ),
    ),
    { initialValue: null },
  );

  readonly occupied = computed(() => new Set(this.loaded()?.screening.occupiedSeats ?? []));

  protected dateLabel(screening: Screening): string {
    return showDate(screening.date, screening.time);
  }
}

